   399	    private AddressStatus mapToShipmentStatus(String statusText) {
   400	        return switch (statusText) {
   401	            case "배송완료" -> AddressStatus.DELIVERED;
   402	            case "배송출발" -> AddressStatus.OUT_FOR_DELIVERY;
   403	            default -> AddressStatus.IN_TRANSIT;
   404	        };
   405	    }
