    11	@Entity @jakarta.persistence.Table(name = "order_shipment")
    12	@Getter
    13	@NoArgsConstructor
    14	@AllArgsConstructor
    15	@Builder
    16	public class FaqAddress extends BaseTimeEntity {
    17	
    18	    @Id
    19	    @GeneratedValue(strategy = GenerationType.IDENTITY)
    20	    private Long id;
    21	
    22	    @OneToOne(fetch = FetchType.LAZY)
    23	    @JoinColumn(name = "order_id", nullable = false)
    24	    private Faq order;
    25	
    26	    private String receiverName;
    27	    private String receiverPhone;
    28	    private String postalCode;
    29	    private String address;
    30	    private String courier;
    31	    private String trackingNumber;
    32	
    33	    @Enumerated(EnumType.STRING)
    34	    private AddressStatus status;
    35	
    36	
    37	    public void assignOrder(Faq order) {
    38	        this.order = order;
    39	    }
    40	
    41	    public void updateTrackingInfo(String courier, String trackingNumber) {
    42	        this.courier = courier;
    43	        this.trackingNumber = trackingNumber;
    44	        this.status = AddressStatus.IN_TRANSIT;
    45	    }
    46	
    47	    public void updateStatus(AddressStatus newStatus) {
    48	        if (this.status == null || this.status.canTransitionTo(newStatus)) {
    49	            this.status = newStatus;
    50	        } else {
    51	            throw new IllegalStateException(
    52	                    "Cannot transition from " + this.status + " to " + newStatus
    53	            );
    54	        }
    55	    }
    56	}
    57	package com.fream.back.domain.address.entity;
    58	
    59	public enum AddressStatus {
    60	    PENDING {
    61	        @Override
    62	        public boolean canTransitionTo(AddressStatus nextStatus) {
    63	            return nextStatus == SHIPPED || nextStatus == CANCELED;
    64	        }
    65	    },
    66	    SHIPPED {
    67	        @Override
    68	        public boolean canTransitionTo(AddressStatus nextStatus) {
    69	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
    70	        }
    71	    },
    72	    IN_TRANSIT {
    73	        @Override
    74	        public boolean canTransitionTo(AddressStatus nextStatus) {
    75	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
    76	                    || nextStatus == DELIVERED;
    77	        }
    78	    },
    79	    OUT_FOR_DELIVERY {
    80	        @Override
    81	        public boolean canTransitionTo(AddressStatus nextStatus) {
    82	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
    83	        }
    84	    },
    85	    DELIVERED {
    86	        @Override
    87	        public boolean canTransitionTo(AddressStatus nextStatus) {
    88	            return false;
    89	        }
    90	    },
    91	    RETURNED {
    92	        @Override
    93	        public boolean canTransitionTo(AddressStatus nextStatus) {
    94	            return nextStatus == CANCELED;
    95	        }
    96	    },
    97	    CANCELED {
    98	        @Override
    99	        public boolean canTransitionTo(AddressStatus nextStatus) {
   100	            return false;
   101	        }
   102	    },
   103	    DELAYED {
   104	        @Override
   105	        public boolean canTransitionTo(AddressStatus nextStatus) {
   106	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
   107	        }
   108	    },
   109	    FAILED_DELIVERY {
   110	        @Override
   111	        public boolean canTransitionTo(AddressStatus nextStatus) {
   112	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
   113	        }
   114	    };
   115	
   116	    public abstract boolean canTransitionTo(AddressStatus nextStatus);
   117	}
