161	    public Faq createInstantOrder(Product buyer, StyleBid saleBid, Long addressId,
162	                                    boolean isWarehouseStorage, NotificationRequestDto paymentRequest) {
163	        try {
164	
165	            if (buyer == null) {
166	                throw new InvalidFaqDataException("구매자 정보가 없습니다.");
167	            }
168	            if (saleBid == null) {
169	                throw new StyleBidNotFoundException("판매 입찰 정보가 없습니다.");
170	            }
171	            if (addressId == null) {
172	                throw new InvalidFaqDataException("배송지 정보가 없습니다.");
173	            }
174	            if (paymentRequest == null) {
175	                throw new InvalidNotificationAddressDataException("결제 정보가 없습니다.");
176	            }
177	
178	
179	            ShipmentResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
180	
181	
182	            Faq order = Faq.builder()
183	                    .user(buyer)
184	                    .totalAmount(saleBid.getBidPrice())
185	                    .status(FaqStatus.PENDING_PAYMENT)
186	                    .build();
187	
188	            order = orderRepository.save(order);
189	
190	
191	            paymentRequest.setOrderId(order.getId());
192	            log.debug("결제 요청 정보: {}", paymentRequest);
193	
194	
195	            try {
196	                FaqItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
197	                order.addOrderItem(orderItem);
198	            } catch (Exception e) {
199	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
200	                throw new FaqItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
201	            }

         Notification payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
         order.assignPayment(payment);

         if (!payment.isSuccess()) {
             throw new RuntimeException("결제 실패: " + payment.getStatus());
         }

         log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());


         FaqAddress shipment = orderShipmentCommandService.createOrderShipment(
                 order,
                 requestDto.getReceiverName(),
                 requestDto.getReceiverPhone(),
                 requestDto.getPostalCode(),
                 requestDto.getAddress()
         );
         order.assignOrderShipment(shipment);
         log.info("배송 정보 생성 완료: 주문ID={}", order.getId());


         if (!order.getStatus().canTransitionTo(FaqStatus.PAYMENT_COMPLETED)) {
             throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
         }
         order.updateStatus(FaqStatus.PAYMENT_COMPLETED);

         if (requestDto.isWarehouseStorage()) {

             Notice warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
             order.assignWarehouseStorage(warehouseStorage);


             if (order.getStatus().canTransitionTo(FaqStatus.PREPARING)) {
                 order.updateStatus(FaqStatus.PREPARING);
             }
             if (order.getStatus().canTransitionTo(FaqStatus.IN_WAREHOUSE)) {
                 order.updateStatus(FaqStatus.IN_WAREHOUSE);
             }
             if (order.getStatus().canTransitionTo(FaqStatus.COMPLETED)) {
                 order.updateStatus(FaqStatus.COMPLETED);
             }

             log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
         } else {

             if (order.getStatus().canTransitionTo(FaqStatus.PREPARING)) {
                 order.updateStatus(FaqStatus.PREPARING);
             }
             log.info("배송 준비 완료: 주문ID={}", order.getId());
         }


         orderRepository.save(order);
         log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());

     } catch (Exception e) {
         log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
         throw e;
     }
 }




 private boolean isOrderAlreadyProcessed(Long orderId) {
     try {
         Faq order = orderRepository.findById(orderId).orElse(null);
         if (order == null) {
             return false;
         }


         FaqStatus currentStatus = order.getStatus();
         return currentStatus != FaqStatus.PENDING_PAYMENT;

     } catch (Exception e) {
         log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
         return false;
     }
 }

